SELECT

FROM agent_tool_call
WHERE id = #{id}
  AND user_id = #{userId}
LIMIT 1

SELECT

FROM agent_tool_call
WHERE session_id = #{sessionId}
  AND status IN ('EXECUTED', 'FAILED')
ORDER BY id DESC
LIMIT #{limit}

mapper.update:
UPDATE agent_tool_call
SET status = #{status},
    failure_type = #{failureType},
    result_summary = #{resultSummary},

    pending_args = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND user_id = #{userId}
  AND status = 'PROPOSED'
